// Auto-generated console icon data URIs for instantaneous, 0ms synchronous rendering.
// Bypasses backend RPC so console icons never flicker, fail, or freeze the UI.
// Regenerate with: python scripts/gen_icon_data.py
export const CONSOLE_ICON_DATA: Record<string, string> = {
    '32x': 'data:image/png;base64,',
    '3ds': 'data:image/png;base64,',
    'dc': 'data:image/png;base64,',
    'default': 'data:image/png;base64,',
    'ds': 'data:image/png;base64,',
    'emu': 'data:image/png;base64,',
    'gb': 'data:image/png;base64,',
    'gba': 'data:image/png;base64,',
    'gbc': 'data:image/png;base64,',
    'gc': 'data:image/png;base64,',
    'genesis': 'data:image/webp;base64,',
    'md': 'data:image/png;base64,',
    'msx': 'data:image/png;base64,',
    'n64': 'data:image/png;base64,',
    'nes': 'data:image/png;base64,',
    'ps1': 'data:image/webp;base64,',
    'ps2': 'data:image/png;base64,',
    'ps3': 'data:image/webp;base64,',
    'ps4': 'data:image/webp;base64,',
    'psp': 'data:image/png;base64,',
    'snes': 'data:image/png;base64,',
    'switch': 'data:image/png;base64,',
    'wii': 'data:image/webp;base64,',
    'wiiu': 'data:image/png;base64,',
    'x360': 'data:image/png;base64,',
    'xbox': 'data:image/png;base64,',
};

export function getBundledConsoleIcon(key?: string | null): string | undefined {
    if (!key) return undefined;
    const clean = key.toLowerCase().replace(/\.(png|webp|svg|jpe?g)$/i, '');
    return CONSOLE_ICON_DATA[clean] ?? undefined;
}
